import { query } from "@/lib/postgres";
import { LIMITS } from "@/config/app-constants";

export interface TokenRow {
  id: string;
  created_by: string;
  created_at: string;
  // TODO: add your columns
}

export async function findAll(
  opts: { limit?: number; offset?: number } = {},
): Promise<TokenRow[]> {
  const limit = Math.min(opts.limit ?? LIMITS.DEFAULT_PAGE_SIZE, LIMITS.MAX_PAGE_SIZE);
  const offset = Math.max(opts.offset ?? 0, 0);
  const { rows } = await query<TokenRow>(
    `SELECT id, created_by, created_at
       FROM public.token
      ORDER BY created_at DESC
      LIMIT $1 OFFSET $2`,
    [limit, offset],
  );
  return rows;
}

export async function findById(id: string): Promise<TokenRow | null> {
  const { rows } = await query<TokenRow>(
    `SELECT id, created_by, created_at
       FROM public.token
      WHERE id = $1`,
    [id],
  );
  return rows[0] ?? null;
}

export async function insert(input: { createdBy: string }): Promise<TokenRow> {
  const { rows } = await query<TokenRow>(
    `INSERT INTO public.token (created_by)
     VALUES ($1)
     RETURNING id, created_by, created_at`,
    [input.createdBy],
  );
  return rows[0];
}

export async function remove(id: string): Promise<boolean> {
  const { rowCount } = await query(
    `DELETE FROM public.token WHERE id = $1`,
    [id],
  );
  return (rowCount ?? 0) > 0;
}
